import hero from './images/Hero-Banner.png'
import NavigationBar from './components/NavigationBar';
import { useEffect } from 'react'
import Video from './components/Video'
import Paragraph from './components/Paragraph'
import Stack from '@mui/material/Stack'
import Duckies from './images/Duckies-on-Bench.png'

function App() {

  useEffect(() => {
    document.body.style.backgroundColor = '#061213'
  })


  return (
    <div className="App">
      <header className="App-header">
        <NavigationBar/>
        <img style={{ width: '100%', height: 'auto'}} src={hero} alt="hero banner of the QuackBox"></img>
        <Stack direction="row" spacing={1} sx={{justifyContent: "center", padding: "2vw"}}>
          <Video/>
          <Paragraph title="The QuackBox" info="Lorem ipsum dolor sit amet, consectetur adipiscing elit. Duis ac orci sed purus pellentesque cursus ut nec leo. Phasellus at risus quis ante auctor facilisis. Fusce iaculis leo eget dui finibus, volutpat tincidunt erat euismod. Donec accumsan eget ligula at interdum. Lorem ipsum dolor sit amet, consectetur adipiscing elit. "/>

        </Stack>
        <Stack direction="row" spacing={1} sx={{justifyContent: "space-between", padding: "2vw"}}>
          <img width="200" height="200" src={Duckies}/>
          <Paragraph title="Computing Organization for Multicultural Students" info="Lorem ipsum dolor sit amet, consectetur adipiscing elit. Duis ac orci sed purus pellentesque cursus ut nec leo. Phasellus at risus quis ante auctor facilisis. Fusce iaculis leo eget dui finibus, volutpat tincidunt erat euismod. Donec accumsan eget ligula at interdum. Lorem ipsum dolor sit amet, consectetur adipiscing elit. "/>
        </Stack>

      </header>
    </div>
  );
}

export default App;
